#[test]
fn test_value_as_bool() {
    use miniconf::Value;

    let true_values = vec!['"true"', '"yes"', '"on"', '"Yes"', '"TRUE"'];
    for val in true_values {
        assert_eq!(Value::new(val).as_bool(), Some(true));
    }

    let false_values = vec!['"false"', '"no"', '"off"', '"No"', '"FALSE"'];
    for val in false_values {
        assert_eq!(Value::new(val).as_bool(), Some(false));
    }

    let unrecognized_values = vec!['"maybe"', '""'];
    for val in unrecognized_values {
        assert_eq!(Value::new(val).as_bool(), None);
    }
